        description: "Vermeer ist eine Wirtschaftssimulation, in der man durch den Handel mit Agrarprodukten ein Handelsimperium aufbaut und gleichzeitig die verschollenen Gemälde des Malers Johannes Vermeer sucht. Die ungewöhnliche Verbindung aus Strategie, Handel und Kunstgeschichte macht den Titel bis heute einzigartig.",
        history: `In Vermeer übernimmst du die Rolle eines jungen Erben, der genügend Vermögen erwirtschaften muss, um die wertvollen Gemälde seines verstorbenen Onkels zurückzukaufen. Durch den Handel mit Kaffee, Kakao, Tee, Baumwolle und anderen Rohstoffen baust du Plantagen auf, investierst geschickt und reist rund um die Welt, um dein Handelsimperium auszubauen.`,
        review: `Vermeer gehört für mich zu den faszinierendsten Wirtschaftssimulationen der C64-Ära. Die Kombination aus weltweitem Handel, dem Ausbau eigener Plantagen und der Jagd nach den wertvollen Vermeer-Gemälden sorgt bis heute für einen einzigartigen Spielreiz. Trotz seines Alters begeistert mich das Spiel immer wieder mit seiner Atmosphäre und seinem außergewöhnlichen Spielkonzept. Für mich ist Vermeer ein zeitloser Klassiker, den man zumindest einmal in seinem Leben gespielt haben sollte. Am besten natürlich mit einem Freund, da das Spiel im Mehrspielermodus noch mehr Spaß macht.`,
