        history: `In Defender of the Crown kämpfst du nach dem Tod König Richards um die Herrschaft über England. Als sächsischer Adliger eroberst du Burgen, führst Armeen in die Schlacht, nimmst an Turnieren teil und versuchst, die Gunst edler Damen zu gewinnen. Ziel ist es, alle Ländereien zu vereinen und selbst die Krone Englands zu erringen.`,
        review: `Defender of the Crown gehört für mich zu den größten Klassikern der Computergeschichte. Die Mischung aus Strategie, Belagerungen, Turnieren und einer für die damalige Zeit atemberaubenden Präsentation war einfach einzigartig. Auch auf dem C64 vermittelt das Spiel bis heute eine fantastische Atmosphäre und zeigt eindrucksvoll, warum Cinemaware legendären Status genießt. Ein absolutes Meisterwerk, das in keiner Retro-Sammlung fehlen sollte.`,
