        publisher: "Strategic-Simulation-Incorporated (SSI)",
        developer: "Don Daglow, Cathryn Mataga, David Bunnett.",
        genre: ["Rollenspiel"],
        description: "Neverwinter Nights ist ein Online-Rollenspiel im Forgotten Realms-Universum, das bereits 1994 gemeinsames Spielen über das Internet ermöglichte. Mit seiner persistenten Spielwelt und kooperativen Abenteuern zählt es zu den wichtigsten Wegbereitern moderner Online-Rollenspiele.",
        history: `Neverwinter Nights entführt dich in die berühmte Stadt Neverwinter der Forgotten Realms, wo du gemeinsam mit anderen Spielern Quests erfüllst, Monster bekämpfst und deinen Charakter stetig weiterentwickelst. Anders als klassische Rollenspiele spielte sich das Abenteuer online auf den Servern von AOL ab. Dadurch entstand eine lebendige Spielwelt, in der hunderte Spieler gleichzeitig Abenteuer erleben konnten.`,
        review: `Neverwinter Nights war seiner Zeit weit voraus und zeigte bereits Anfang der 1990er-Jahre, welches Potenzial Online-Rollenspiele besitzen. Die Verbindung aus klassischem Dungeons & Dragons, einer persistierenden Spielwelt und dem gemeinsamen Spielen mit anderen machte das Spiel zu einem echten Pionier. Auch wenn die Technik heute längst überholt ist, beeindruckt mich bis heute, wie visionär dieses Projekt damals war.`,
