        page: "regent.html",
        featured: false,
        title: "Regent - Collectors Edition",
        system: "Amiga",
        year: 1994,
        publisher: "Martin ECONOMIC Simulations (MES)",
        developer: "Martin Martin, Elmar Martin, Dietmar Assmann",
        genre: ["Strategie", "Simulation"],
        description: "Regent verbindet Wirtschaft, Politik und Kriegsführung in einer mittelalterlichen Strategiesimulation. Mit Handel, Produktion und geschickter Verwaltung kämpft man um die Vorherrschaft im Heiligen Römischen Reich – ein komplexer, heute fast vergessener Titel mit deutlichen Anleihen bei Kaiser.",
        history: `In Regent übernimmst du die Verantwortung für ein mittelalterliches Königreich und versuchst, durch geschicktes Wirtschaften und kluge Entscheidungen Wohlstand und Einfluss zu gewinnen. Du verwaltest Finanzen, handelst mit Ressourcen, investierst in den Ausbau deines Landes und musst gleichzeitig auf die Bedürfnisse deiner Bevölkerung achten. Nur wer langfristig plant und seine Mittel sinnvoll einsetzt, kann ein erfolgreicher Herrscher werden.`,
        review: `Regent zählt für mich zu den unterschätzten Wirtschaftssimulationen auf dem Amiga. Das Spiel setzt weniger auf spektakuläre Grafik als auf strategische Tiefe und motivierende Langzeitplanung. Gerade Fans klassischer Managementspiele kommen hier voll auf ihre Kosten. Wer sich die Zeit nimmt, die Spielmechaniken kennenzulernen, entdeckt einen Titel, der auch heute noch viel Spielspaß bietet.`,
