        history: `In Phantasie stellst du eine Gruppe von bis zu sechs Abenteurern zusammen und begibst dich auf eine gefährliche Reise durch eine weitläufige Fantasywelt. Städte, Dungeons und unzählige Zufallsbegegnungen warten darauf, erkundet zu werden, während deine Helden Erfahrung sammeln und immer mächtiger werden. Ziel ist es, den finsteren Hexenkönig Nikademus zu besiegen und das Königreich vor seinem Untergang zu bewahren.`,
        review: `Phantasie gehört für mich zu den großen Rollenspielklassikern auf dem Commodore 64. Das Spiel bietet erstaunlich viel Tiefgang, ein motivierendes Charaktersystem und spannende rundenbasierte Kämpfe. Zwar verlangt die Bedienung heute etwas Eingewöhnung, doch wer klassische Computer-RPGs liebt, wird schnell erkennen, warum Phantasie bis heute einen hervorragenden Ruf genießt. Für mich ist es einer der besten Vertreter des Genres auf dem C64.`,
