        history: `Burntime spielt in einer Welt, die nach einem Atomkrieg fast vollständig zerstört wurde. Als Anführer einer kleinen Gruppe Überlebender bereist du verlassene Städte, rekrutierst Gefährten, sammelst Ausrüstung und kämpfst um die Kontrolle wichtiger Siedlungen. Nahrung, Wasser und Schlafplätze sind dabei ebenso entscheidend wie taktische Kämpfe und geschicktes Ressourcenmanagement. Ziel ist es, nach und nach alle rivalisierenden Fraktionen zu besiegen und die Herrschaft über das Ödland zu übernehmen.`,
        review: `Burntime war seiner Zeit weit voraus. Die offene Spielwelt, das Überleben in einer feindlichen Umgebung und die Mischung aus Rollenspiel, Strategie und Ressourcenmanagement sorgen für ein einzigartiges Spielerlebnis. Besonders beeindruckend finde ich, wie viele Entscheidungen der Spieler selbst treffen kann und wie dynamisch sich die Spielwelt entwickelt. Auch heute besitzt Burntime noch eine faszinierende Atmosphäre und gehört für mich zu den außergewöhnlichsten Titeln auf dem Amiga.`,
