        title: "Die Fugger",
        system: "C64",
        year: 1988,
        publisher: "The Electric Ballhaus, BOMICO",
        developer: "Lars Martensen, Matthias Kriesell",
        genre: ["Strategie"],
        description: "Fugger ist eine anspruchsvolle Wirtschaftssimulation im Europa der Renaissance. Durch geschickten Handel, Investitionen und politischen Einfluss versuchst du, deine Handelsdynastie zur mächtigsten Familie des Kontinents auszubauen.",
        history: `In Fugger schlüpfst du in die Rolle einer aufstrebenden Kaufmannsfamilie im Europa des 16. Jahrhunderts. Zwischen zahlreichen Städten handelst du mit Waren, gründest Niederlassungen, investierst in Betriebe und baust dein Vermögen kontinuierlich aus. Gleichzeitig gilt es, politische Ämter zu erwerben, Konkurrenten auszustechen und den Einfluss der eigenen Familie stetig zu vergrößern. Nur wer wirtschaftliches Geschick mit langfristiger Planung verbindet, kann schließlich zur bedeutendsten Handelsdynastie Europas aufsteigen.`,
        review: `Fugger zählt für mich zu den besten Wirtschaftssimulationen, die jemals für den Commodore 64 erschienen sind. Das Spiel bietet eine beeindruckende strategische Tiefe und motiviert durch seinen gelungenen Mix aus Handel, Politik und Unternehmensaufbau. Trotz der vergleichsweise schlichten Präsentation entwickelt sich schnell der Ehrgeiz, immer effizientere Handelsrouten aufzubauen und die Konkurrenz hinter sich zu lassen. Für Fans komplexer Strategiespiele gehört Fugger auch heute noch zu den absoluten Genre-Highlights.`,
        trivia: [
        "Entwickelt von Starbyte Software und 1988 veröffentlicht.",
        "Das Spiel orientiert sich lose an der historischen Kaufmannsfamilie Fugger aus Augsburg.",
        "Fugger erschien für mehrere Heimcomputer und gilt bis heute als einer der bekanntesten deutschsprachigen Wirtschaftssimulationen der 1980er-Jahre."
    ],
        worthPlaying: `Fugger begeistert auch heute noch durch seine enorme strategische Tiefe und den gelungenen Mix aus Handel, Politik und langfristiger Planung. Wer klassische Wirtschaftssimulationen schätzt, findet hier einen zeitlosen Klassiker, der zu den besten Vertretern seines Genres auf dem C64 zählt.`,
