        id: 22,
        folder: "the_7th_guest",
        scanBy: "Magisthan",
        page: "the_7th_guest.html",
        featured: false,
        title: "The 7th Guest",
        system: "PC",
        year: 1993,        
        publisher: "Virgin Games",
        developer: "Trilobyte",
        genre: ["Adventure", "Puzzle"],
        description: "The 7th Guest verbindet eine düstere Spukhausgeschichte mit kniffligen Rätseln, vorgerenderten 3D-Kulissen und aufwendig inszenierten FMV-Sequenzen.",
        history: `Im Mittelpunkt von The 7th Guest steht die unheimliche Villa des Spielzeugmachers Henry Stauf. Sechs Gäste wurden einst in das Haus eingeladen und verschwanden dort unter mysteriösen Umständen. Als Spieler erkundest du die verlassen wirkenden Räume, beobachtest geisterhafte Szenen aus der Vergangenheit und löst zahlreiche Rätsel, um herauszufinden, was mit den Gästen geschah und wer der geheimnisvolle siebte Gast ist. Das Spiel erzählt seine Geschichte überwiegend durch Full-Motion-Video-Sequenzen und vorgerenderte Animationen, die Anfang der 1990er-Jahre technisch außergewöhnlich wirkten.`,
        review: `The 7th Guest ist heute vor allem deshalb faszinierend, weil das Spiel sehr deutlich zeigt, welche Aufbruchsstimmung die CD-ROM Anfang der 1990er-Jahre ausgelöst hat. Die vorgerenderten Räume, digitalisierten Schauspieler und umfangreichen Videosequenzen waren 1993 spektakulär und machten den Titel zu einem wichtigen Vorzeigespiel der neuen Technik. Spielerisch besteht das Abenteuer allerdings hauptsächlich aus einzelnen Logik- und Denkaufgaben, deren Qualität recht unterschiedlich ausfällt. Manche Rätsel funktionieren auch heute noch hervorragend, andere wirken eher wie Hindernisse zwischen den nächsten Filmszenen. Trotzdem besitzt The 7th Guest mit seiner bizarren Atmosphäre, der Musik und der eigenwilligen Inszenierung einen ganz besonderen Charme. Als historisches Stück PC-Spielegeschichte ist das Spiel deshalb auch heute noch ausgesprochen interessant.`,
        trivia: [
                  "The 7th Guest gehörte Anfang der 1990er-Jahre zu den bekanntesten Spielen, mit denen die Möglichkeiten der damals neuen CD-ROM-Laufwerke demonstriert wurden.",
                  "Die Entwickler Rob Landeros und Graeme Devine gründeten Trilobyte mit Unterstützung von Virgin speziell für die Entwicklung des Spiels.",
                  "Statt klassischer zweidimensionaler Räume setzte das Spiel auf vorgerenderte 3D-Animationen und kombinierte diese mit digitalisierten Schauspielern in Full-Motion-Video-Sequenzen."
        ],
        worthPlaying: `The 7th Guest ist heute weniger wegen seiner einzelnen Rätsel als wegen seiner besonderen Stellung in der PC-Spielegeschichte interessant. Das Spiel vermittelt hervorragend, warum CD-ROM, vorgerenderte Grafik und Full-Motion-Video 1993 als Zukunft des Computerspiels galten. Wer sich für frühe Multimedia-Spiele, ungewöhnliche Adventures oder die Geschichte der PC-CD-ROM interessiert, sollte Staufs Villa deshalb zumindest einmal besucht haben.`,
