        page: "7cities_of_gold_c64.html",
        featured: true,
        title: "The Seven Cities of Gold",
        system: "C64",
        year: 1984,        
        publisher: "Electronic Arts",
        developer: "Ozark Softscape",
        genre: ["Rollenspiel", "Strategie"],
        description: "The Seven Cities of Gold verbindet Erkundung, Handel und historische Strategie mit einer für 1984 ungewöhnlich offenen Spielwelt und lässt dich auf eigene Faust die Neue Welt entdecken.",
        history: `In The Seven Cities of Gold übernimmst du die Rolle eines spanischen Entdeckers gegen Ende des 15. Jahrhunderts. Mit einem Schiff, einer Mannschaft und begrenzten Vorräten brichst du von Europa aus in Richtung der unbekannten Neuen Welt auf. Dort erkundest du riesige, teilweise zufällig erzeugte Landmassen, gründest Missionen, handelst mit den einheimischen Völkern und versuchst, Gold und Ruhm für die spanische Krone zu gewinnen. Dabei bleibt dir weitgehend selbst überlassen, ob du friedlich handelst oder mit Gewalt vorgehst. Nach jeder Expedition kehrst du nach Spanien zurück, wo deine Erfolge bewertet werden und du neue Mittel für weitere Reisen erhalten kannst.`,
        review: `The Seven Cities of Gold ist ein bemerkenswert frühes Beispiel dafür, wie viel spielerische Freiheit bereits 1984 möglich war. Statt den Spieler durch feste Missionen zu führen, überlässt das Spiel ihm weitgehend selbst, wohin er segelt, welche Gebiete er erkundet und wie er mit den Bewohnern der Neuen Welt umgeht. Besonders beeindruckend ist die Größe der Spielwelt, die durch ein Verfahren zur Erzeugung neuer Kontinente praktisch immer wieder andere Expeditionen ermöglicht. Aus heutiger Sicht wirkt die Darstellung der europäischen Eroberung Amerikas verständlicherweise deutlich problematischer als zur Zeit der Veröffentlichung, spielmechanisch bleibt die Mischung aus Erkundung, Ressourcenverwaltung und Strategie jedoch ausgesprochen interessant. Gerade auf dem C64 zeigt The Seven Cities of Gold eindrucksvoll, dass komplexe offene Spielwelten keine Erfindung moderner Computerspiele sind.`,
        trivia: [
                  "The Seven Cities of Gold wurde unter der Leitung von Danielle Bunten Berry entwickelt, die zuvor bereits mit M.U.L.E. einen der bekanntesten Strategieklassiker der frühen 1980er-Jahre geschaffen hatte.",
                  "Neben einer historischen Karte der Neuen Welt konnte das Spiel auch neue Kontinente generieren, wodurch sich weitere Expeditionen mit unbekannten Landmassen spielen ließen.",
                  "Das Spiel erschien 1984 gleichzeitig für Atari-8-Bit-Computer, Apple II und Commodore 64; spätere Umsetzungen folgten unter anderem für IBM-PC und Amiga."
        ],
        worthPlaying: `The Seven Cities of Gold lohnt sich heute vor allem wegen seiner erstaunlich offenen Spielstruktur. Erkunden, handeln, Vorräte verwalten und selbst entscheiden, wie eine Expedition verlaufen soll – viele Elemente, die heute selbstverständlich erscheinen, waren 1984 ausgesprochen ungewöhnlich. Wer sich für frühe Open-World-Konzepte und die Entwicklung moderner Strategiespiele interessiert, findet hier einen besonders spannenden Meilenstein der Computerspielgeschichte.`,
