        id: 26,
        folder: "abandoned_places",
        scanBy: "Magisthan",
        page: "abandoned_places.html",
        featured: false,
        title: "Abandoned Places: A Time for Heroes",
        system: "Amiga",
        year: 1992,        
        publisher: "International Computer Entertainment",
        developer: "ArtGame",
        genre: ["Rollenspiel", "Dungeon Crawler"],
        description: "Abandoned Places verbindet klassische Echtzeit-Dungeons im Stil von Dungeon Master mit einer frei erkundbaren Oberwelt, Städten und einer umfangreichen Fantasywelt.",
        history: `In Abandoned Places: A Time for Heroes übernimmst du eine Gruppe aus vier Helden, die das Königreich Kalynthia vor dem bösen Erzmagier Bronagh retten sollen. Anders als viele klassische Dungeon Crawler beschränkt sich das Abenteuer nicht auf unterirdische Verliese. Auf einer zweidimensional dargestellten Oberwelt reist du zwischen Städten, Dörfern und verschiedenen Schauplätzen, sammelst Hinweise und bereitest deine Gruppe auf kommende Gefahren vor. Sobald du einen Dungeon betrittst, wechselt das Spiel in eine dreidimensionale Ego-Perspektive im Stil von Dungeon Master. Kämpfe laufen in Echtzeit ab, während Waffen, Zaubersprüche und Gegenstände direkt über die Benutzeroberfläche eingesetzt werden.`,
        review: `Abandoned Places gehört zu den interessanteren Dungeon Crawlern auf dem Amiga, weil es sich nicht damit begnügt, den Spieler ausschließlich durch endlose Verliese zu schicken. Die Kombination aus frei erkundbarer Oberwelt, Städten und klassischen 3D-Dungeons sorgt für deutlich mehr Abwechslung als bei vielen zeitgenössischen Genrevertretern. Besonders die Größe der Spielwelt und die Freiheit bei der Erkundung waren Anfang der 1990er-Jahre bemerkenswert. Technisch zeigt sich das Spiel allerdings weniger beeindruckend: Grafik und Animationen wirken teilweise schlicht und die Bedienung verlangt einiges an Eingewöhnung. Wer darüber hinwegsehen kann, bekommt jedoch ein umfangreiches und anspruchsvolles Rollenspiel, das Dungeon-Master-Spielmechanik mit einer ungewöhnlich offenen Welt verbindet.`,
        trivia: [
                  "Abandoned Places wurde vom ungarischen Entwicklerstudio ArtGame entwickelt und war von Advanced Dungeons & Dragons sowie Dungeon Master inspiriert.",
                  "Die Entwicklung begann bereits 1990; Electronic Arts lehnte das Spiel unter anderem ab, weil der Publisher kurz zuvor Raven Softwares Black Crypt unter Vertrag genommen hatte.",
                  "Das Spiel wechselt zwischen einer zweidimensionalen Oberwelt und dreidimensional dargestellten Echtzeit-Dungeons, wodurch es sich von vielen reinen Dungeon Crawlern seiner Zeit unterscheidet."
        ],
        worthPlaying: `Abandoned Places lohnt sich heute besonders für Fans klassischer Amiga-Rollenspiele und Dungeon Crawler. Die Verbindung aus Oberwelterkundung, Städten, Gruppenverwaltung und Echtzeit-Dungeons verleiht dem Spiel eine überraschende Freiheit. Präsentation und Bedienung sind sichtbar gealtert, doch wer sich davon nicht abschrecken lässt, entdeckt einen umfangreichen und heute etwas in Vergessenheit geratenen Vertreter des Genres.`,
