        id: 29,
        folder: "anarchy",
        scanBy: "Magisthan",
        page: "anarchy.html",
        featured: false,
        title: "Anarchy",
        system: "Amiga",
        year: 1990,        
        publisher: "Psygnosis",
        developer: "WJS Design",
        genre: ["Shoot 'em up", "Action"],
        description: "Anarchy ist ein schnelles horizontales Shoot’em Up im Stil von Defender, in dem der Spieler in einer futuristischen Welt gegen immer neue Angriffswellen und mächtige Gegner antritt.",
        history: `Anarchy erschien 1990 für Amiga und Atari ST und wurde von WJS Design entwickelt. Das Spiel orientiert sich deutlich am Arcade-Klassiker Defender: Du steuerst ein Raumschiff durch seitlich scrollende, in sich geschlossene Landschaften und bekämpfst feindliche Einheiten, während du gleichzeitig deine Umgebung und die Position von Gegnern über das Radar im Blick behalten musst. Neben regulären Gegnerwellen gibt es stärkere Feinde und Bossgegner, außerdem lassen sich verschiedene Waffenverbesserungen und zusätzliche Feuerkraft einsammeln. Das Spiel entstand ursprünglich aus dem Versuch von Wayne Smithson, auf dem Atari ST besonders flüssiges horizontales Scrolling zu realisieren. Die Amiga-Version profitierte dabei von der leistungsfähigen Hardware und setzte das schnelle Spielprinzip entsprechend dynamisch um.`,
        review: `Anarchy ist eines jener Spiele, bei denen die Verwandtschaft mit Defender praktisch sofort auffällt. Schnelles horizontales Scrolling, hektische Gegnerwellen, Radar und die ständige Gefahr, von mehreren Seiten gleichzeitig unter Druck gesetzt zu werden, bestimmen den Ablauf. Spielerisch funktioniert das grundsätzlich gut, allerdings erreicht Anarchy nicht ganz die Präzision und Eleganz seines großen Vorbilds. Die großen Sprites und die teilweise unübersichtlichen Gefechte können dafür sorgen, dass man schneller die Orientierung verliert, als einem lieb ist. Dafür sorgen Waffen-Upgrades, zusätzliche Feuerkraft und Bossgegner für etwas mehr Abwechslung. Wer klassische Arcade-Shooter mag und ein Herz für kompromisslose Amiga-Action hat, bekommt hier einen soliden, wenn auch nicht herausragenden Vertreter des Genres.`,
        trivia: [
                  "Anarchy wurde von Wayne Smithson bei WJS Design entwickelt und erschien 1990 für Amiga und Atari ST.",
                  "Der ursprüngliche Arbeitstitel lautete „It Can't Be Done“, weil Wayne Smithson mit dem Projekt beweisen wollte, dass auf dem Atari ST flüssiges horizontales Scrolling möglich war.",
                  "Die Cover-Illustration stammt von Melvyn Grant; das auffällige Lettering wurde von Roger Dean gestaltet."
        ],
        worthPlaying: `Anarchy lohnt sich heute vor allem für Fans klassischer horizontaler Shoot’em Ups und Defender-Varianten. Das Spiel ist schnell, direkt und besitzt genau jene kompromisslose Arcade-Struktur, die viele Amiga-Shooter dieser Zeit auszeichnet. Besonders interessant ist zudem die technische Entstehungsgeschichte rund um das ursprünglich als Experiment entwickelte Scrolling.`,
