        genre: ["Fußballmanager", "Wirtschaftssimulation", "Strategie"],
        description: "Anstoss 2: Verlängerung! erweitert den erfolgreichen Fußballmanager um zahlreiche Detailverbesserungen, eine überarbeitete Länderauswahl und die Rückkehr des Nationalmannschaftsmodus.",
        history: `Anstoss 2: Verlängerung! erschien im Februar 1998 als Erweiterung für den erfolgreichen Fußballmanager Anstoss 2. Ascaron griff dabei zahlreiche Wünsche und Rückmeldungen der Spieler auf und ergänzte das Hauptspiel um neue Funktionen und Detailverbesserungen. Eine der wichtigsten Neuerungen war die Rückkehr des Nationalmannschaftsmodus, der im ursprünglichen Anstoss 2 zunächst weggefallen war. Nun konnte der Spieler zusätzlich zu seinem Verein eine Nationalmannschaft übernehmen und beide Aufgaben miteinander verbinden. Außerdem wurde die Länderauswahl überarbeitet, sodass mehrere Länder gleichzeitig in die laufende Karriere einbezogen werden konnten. Verlängerung! war kein eigenständiges Spiel, sondern setzte eine Installation von Anstoss 2 voraus. Noch im selben Jahr wurden Hauptspiel und Erweiterung gemeinsam als Anstoss 2 Gold veröffentlicht.`,
        review: `Verlängerung! ist ein gutes Beispiel dafür, wie eine Erweiterung funktionieren sollte: Statt das Hauptspiel einfach nur um ein paar zusätzliche Daten zu ergänzen, griff Ascaron gezielt Punkte auf, die Spielern bei Anstoss 2 gefehlt hatten. Besonders die Rückkehr der Nationalmannschaft sorgt dafür, dass eine lange Managerkarriere noch abwechslungsreicher wird. Gleichzeitig wurden zahlreiche kleinere Bereiche überarbeitet und erweitert, ohne das angenehm zugängliche Grundprinzip unnötig kompliziert zu machen. Wer Anstoss 2 intensiv gespielt hat, bekommt mit Verlängerung! deshalb genau das, was der Titel verspricht: keine Revolution, sondern eine sehr gelungene zweite Halbzeit für einen ohnehin schon hervorragenden Fußballmanager.`,
        trivia: [
                  "Anstoss 2: Verlängerung! erschien im Februar 1998 als Add-on und benötigt das ursprüngliche Anstoss 2.",
                  "Mit der Erweiterung kehrte der Nationalmannschaftsmodus zurück, sodass der Spieler gleichzeitig einen Verein und eine Nationalmannschaft betreuen konnte.",
                  "Noch 1998 wurden Anstoss 2 und Verlängerung! gemeinsam als Anstoss 2 Gold veröffentlicht; diese Fassung enthielt zusätzlich weitere kleinere Verbesserungen."
        ],
        worthPlaying: `Anstoss 2: Verlängerung! lohnt sich heute vor allem zusammen mit dem ursprünglichen Anstoss 2. Die Erweiterung ergänzt einige der Funktionen, die dem Grundspiel noch gefehlt hatten, und macht insbesondere langfristige Managerkarrieren abwechslungsreicher. Wer Anstoss 2 in seiner weitgehend vollständigen ursprünglichen Form erleben möchte, sollte auf Verlängerung! deshalb kaum verzichten.`,
