        id: 33,
        folder: "asterix_im_morgenland",
        scanBy: "Magisthan",
        page: "asterix_im_morgenland.html",
        featured: false,
        title: "Asterix im Morgenland",
        system: "C64",
        year: 1987,        
        publisher: "Coktel Vision",
        developer: "Coktel Vision",
        genre: ["Adventure", "Action-Adventure"],
        description: "Asterix im Morgenland ist ein comicbasiertes Action-Adventure, das Asterix und Obelix auf eine Reise nach Indien schickt, um Troubadix' Stimme wiederherzustellen und Prinzessin Orandschade zu retten.",
        history: `Asterix im Morgenland basiert auf dem gleichnamigen Asterix-Comic und schickt Asterix, Obelix und Troubadix auf eine ungewöhnliche Reise nach Indien. Dort soll Troubadix mit seinem Gesang Regen herbeirufen und damit eine schwere Dürre beenden. Unterwegs verliert der Barde jedoch seine Stimme, sodass Asterix und Obelix zunächst ein Heilmittel finden müssen. Gleichzeitig gilt es, Prinzessin Orandschade vor ihrem Schicksal zu bewahren. Spielerisch verbindet das Spiel verschiedene Adventure- und Actionelemente. Die einzelnen Szenen werden aus unterschiedlichen Perspektiven dargestellt und verlangen sowohl richtige Entscheidungen als auch Geschicklichkeit. Die deutsche C64-Version erschien 1987 und gehört zu den frühen Asterix-Umsetzungen von Coktel Vision.`,
        review: `Asterix im Morgenland sieht auf den ersten Blick ausgesprochen sympathisch aus. Die Figuren sind klar erkennbar, viele Szenen orientieren sich sichtbar an den Comicvorlagen und gerade Asterix-Fans werden einige bekannte Motive wiedererkennen. Spielerisch ist das Abenteuer allerdings deutlich weniger überzeugend. Viele Situationen basieren auf einfachen Auswahlentscheidungen oder kurzen Actionsequenzen, deren Ablauf nicht immer besonders nachvollziehbar ist. Dadurch entsteht schnell das Gefühl, eher verschiedene kleine Szenen abzuarbeiten als ein zusammenhängendes Adventure zu spielen. Besonders problematisch ist, dass manche Entscheidungen stark vom Ausprobieren abhängen. Als Asterix-Kuriosität besitzt das Spiel dennoch einen gewissen Charme und vermittelt mit seinen farbenfrohen Bildern durchaus etwas von der Atmosphäre der Comics.`,
        trivia: [
                  "Das Spiel basiert auf dem 1987 erschienenen Comicband „Asterix im Morgenland“, dessen französischer Originaltitel „Astérix chez Rahàzade“ lautet.",
                  "Asterix im Morgenland erschien international unter verschiedenen Titeln, darunter „Asterix and the Magic Carpet“ und „Astérix chez Rahàzade“.",
                  "Die Cover-Illustration wird in den C64-Credits Albert Uderzo zugeschrieben, dem langjährigen Zeichner und Mitschöpfer von Asterix."
        ],
        worthPlaying: `Asterix im Morgenland lohnt sich heute vor allem für Asterix-Fans und Sammler ungewöhnlicher Comicumsetzungen. Spielerisch besitzt das Abenteuer einige deutliche Schwächen, doch die Nähe zur Vorlage und die authentische Optik machen es zu einem interessanten Stück Lizenzspielgeschichte der späten 1980er-Jahre.`,
