        id: 34,
        folder: "athanor_2",
        scanBy: "Magisthan",
        page: "athanor_2.html",
        featured: false,
        title: "Athanor 2: La Légende des Hommes-Oiseaux",
        system: "Amiga",
        year: 2021,        
        publisher: "Safar Games",
        developer: "Safar Games",
        genre: ["Adventure", "Point-and-Click", "Fantasy"],
        description: "Athanor 2: La Légende des Hommes-Oiseaux ist ein klassisches Point-and-Click-Adventure, das bewusst die Atmosphäre früher Grafikadventures aufgreift und seine Rätsel sogar mit physischen Gegenständen aus der Spielbox verbindet.",
        history: `Athanor 2: La Légende des Hommes-Oiseaux setzt die Geschichte des ursprünglichen Athanor fort. Nachdem die Geheimnisse der Abtei gelöst wurden, begibt sich der Held diesmal auf die Suche nach seinen eigenen Ursprüngen. Dabei führt ihn die Reise durch vier größere Schauplätze, an denen neue Figuren, zahlreiche Gegenstände und unterschiedliche Rätsel auf ihn warten. Die Amiga-Version wurde ab 2018 umgesetzt und erschien schließlich 2021. Sie wurde speziell für klassische OCS- und ECS-Amigas mit mindestens 1 MB Speicher entwickelt. Das Spiel verwendet handgezeichnete Illustrationen, die für den Amiga digitalisiert und in 32 Farben umgesetzt wurden. Besonders ungewöhnlich ist die enge Verbindung zwischen Spiel und Verpackung: Mehrere Rätsel lassen sich nur lösen, indem Hinweise und physische Gegenstände aus der Bigbox verwendet werden.`,
        review: `Athanor 2 ist genau die Art von Spiel, die zeigt, dass klassische Amiga-Adventures auch Jahrzehnte nach der ursprünglichen Blütezeit noch funktionieren können. Statt moderne Komfortfunktionen nachzubauen, orientiert sich das Spiel bewusst an alten Grafikadventures und verlangt Aufmerksamkeit, Geduld und manchmal auch eine gewisse Bereitschaft zum Pixelhunting. Besonders stark ist die Atmosphäre. Die handgezeichneten Bilder wirken ungewöhnlich detailliert und verleihen den einzelnen Schauplätzen einen fast illustrativen Charakter. Richtig außergewöhnlich wird Athanor 2 durch die physischen Gegenstände aus der Box, die tatsächlich Bestandteil einiger Rätsel sind. Dadurch erinnert das Spiel an eine Zeit, in der Handbücher, Karten und Beilagen noch zum eigentlichen Spielerlebnis gehörten. Das kann gelegentlich umständlich sein, macht Athanor 2 aber gleichzeitig zu einem ausgesprochen besonderen Retro-Erlebnis.`,
        trivia: [
                  "Die Amiga-Version von Athanor 2 wurde von François Gutherz programmiert und basiert auf der von Eric Safar entworfenen Geschichte und Spielwelt.",
                  "Die ursprünglichen Illustrationen stammen von Angel Bautista; François Gutherz und Vincent Jambut bereiteten und kolorierten die Grafiken für die Amiga-Version.",
                  "Die physische Box enthält mehrere Gegenstände und Hinweise, die direkt zur Lösung bestimmter Rätsel benötigt werden und damit Bestandteil des eigentlichen Spielkonzepts sind."
        ],
        worthPlaying: `Athanor 2 lohnt sich heute besonders für Adventure-Fans und Sammler physischer Retrospiele. Die Kombination aus klassischem Point-and-Click-Gameplay, aufwendig gezeichneten Bildern und echten Gegenständen aus der Verpackung schafft ein Spielerlebnis, das sich bewusst an die großen Adventure-Zeiten der 1980er- und frühen 1990er-Jahre anlehnt. Gerade auf echter Amiga-Hardware ist es ein faszinierendes Beispiel dafür, was moderne Entwickler noch immer aus dem System herausholen können.`,
