        developer: "Psygnosis",
        genre: ["Action", "Plattform", "Fantasy"],
        description: "Barbarian ist ein düsteres Fantasy-Actionspiel von Psygnosis, in dem sich ein einsamer Krieger durch gefährliche Landschaften, Fallen und Monster kämpft.",
        history: `Barbarian erschien 1987 für Amiga und Atari ST und gehört zu den frühen Eigenentwicklungen von Psygnosis. Du steuerst einen muskulösen Krieger durch eine düstere Fantasywelt, in der zahlreiche Gegner, Fallen und Hindernisse auf dich warten. Das Spiel kombiniert seitlich scrollende Action mit Plattformelementen und einem ungewöhnlichen Steuerungssystem, bei dem viele Aktionen direkt über Tastaturbefehle ausgelöst werden. Neben Schwertkämpfen musst du klettern, springen, Gegenstände verwenden und dich durch zunehmend gefährlichere Abschnitte kämpfen. Die Amiga-Version fiel zur damaligen Zeit besonders durch ihre großen Figuren, detaillierten Animationen und eine aufwendige Eröffnungssequenz auf.`,
        review: `Barbarian ist ein typisches frühes Psygnosis-Spiel: technisch beeindruckend, optisch ungewöhnlich und gleichzeitig spielerisch etwas sperrig. Gerade die großen Figuren und die düstere Fantasygrafik vermitteln sofort jene Atmosphäre, für die Psygnosis später berühmt wurde. Weniger überzeugend ist die Steuerung. Viele Aktionen sind umständlich gelöst und verlangen deutlich mehr Eingewöhnung als bei vergleichbaren Actionspielen. Wer sich darauf einlässt, bekommt jedoch ein interessantes Stück früher Amiga-Geschichte. Besonders die Präsentation und das charakteristische Roger-Dean-Artwork machen Barbarian bis heute unverwechselbar.`,
        trivia: [
                  "Barbarian wurde von David H. Lawson entworfen und programmiert; Garvan Corbett war für Animationen und Grafik verantwortlich.",
                  "Die Amiga-Version besitzt eine auffällige Eröffnungssequenz mit digitalisierten Soundeffekten, die 1987 technisch sehr beeindruckend wirkte.",
                  "Die Cover-Illustration stammt von Roger Dean und basiert auf seinem Werk „Red Dragon“."
        ],
        worthPlaying: `Barbarian lohnt sich heute vor allem für Fans früher Psygnosis-Spiele und für Spieler, die sich für die grafische Entwicklung des Amiga interessieren. Die Steuerung ist gewöhnungsbedürftig, doch das düstere Design, die großen Figuren und das ikonische Roger-Dean-Cover machen das Spiel zu einem sehr typischen Vertreter der frühen Psygnosis-Ära.`,
