        id: 38,
        folder: "battle_isle_2_scenery_cd",
        scanBy: "Magisthan",
        page: "battle_isle_2_scenery_cd.html",
        featured: false,
        title: "Battle Isle 2: Scenery CD - Das Erbe des Titan",
        system: "PC",
        year: 1994,        
        publisher: "Blue Byte Software GmbH",
        developer: "Blue Byte Software GmbH",
        genre: ["Strategie", "Rundenstrategie", "Add-on"],
        description: "Battle Isle 2: Scenery CD - Das Erbe des Titan erweitert Battle Isle 2 um eine neue Kampagne, zusätzliche Missionen und eine Fortsetzung der Geschichte auf dem Planeten Chromos.",
        history: `Battle Isle 2: Scenery CD - Das Erbe des Titan erschien 1994 als umfangreiche Erweiterung für Battle Isle 2. Die Handlung setzt nach der Zerstörung von Titan-Net ein. Val Haris versucht, auf Chromos eine demokratische Regierung aufzubauen, doch der Minister Argok Kraal reißt mit Unterstützung des mächtigen Medienkonzerns STAG die Macht an sich. Der Spieler beginnt seine Kampagne auf einer Gefängnisinsel und muss sich Schritt für Schritt gegen Kraal, seine Verbündeten und mehrere militärische Fraktionen durchsetzen. Spielerisch bleibt das Add-on dem bewährten Hexfeld-System von Battle Isle 2 treu und erweitert dieses vor allem um neue Karten, Missionen und Storyelemente. Die Kampagne ist deutlich stärker erzählerisch eingebettet als viele klassische Strategiespiel-Erweiterungen jener Zeit.`,
        review: `Das Erbe des Titan ist genau die Art von Erweiterung, die Battle-Isle-Fans damals gebraucht haben. Statt lediglich ein paar zusätzliche Karten zu liefern, setzt Blue Byte die Geschichte konsequent fort und verpackt die neuen Missionen in eine eigenständige Kampagne. Spielerisch bleibt alles vertraut: Einheiten bewegen, Gelände nutzen, Versorgung sichern und den Gegner möglichst effizient ausmanövrieren. Gerade weil am eigentlichen Regelwerk kaum etwas verändert wurde, richtet sich die Scenery CD klar an Spieler, die mit Battle Isle 2 bereits vertraut sind. Für diese Zielgruppe funktioniert das Add-on hervorragend. Die neuen Szenarien sind anspruchsvoll, abwechslungsreich und nutzen die vorhandenen Systeme deutlich konsequenter aus. Wer mit Battle Isle 2 Spaß hatte, bekommt hier im Grunde genau das, was man sich von einer klassischen Erweiterung erhofft: mehr Inhalt, mehr Herausforderung und eine Fortsetzung der Geschichte.`,
        trivia: [
                  "Die Scenery CD setzt die Handlung von Battle Isle 2 unmittelbar fort und führt mit Argok Kraal einen neuen zentralen Gegenspieler ein.",
                  "Das Add-on unterstützt wie Battle Isle 2 Mehrspielerpartien mit bis zu fünf Spielern und bietet zusätzlich Netzwerk- und Nullmodem-Unterstützung.",
                  "Produzent war Thomas Hertzler; an Programmierung und Design arbeiteten unter anderem Bernhard Ewers, Patric Lagny, Thomas Häuser und Rolf Neumann."
        ],
        worthPlaying: `Battle Isle 2: Scenery CD - Das Erbe des Titan lohnt sich heute vor allem für Spieler, die Battle Isle 2 bereits abgeschlossen haben und noch mehr von dessen taktischem Hexfeld-System möchten. Die neue Kampagne bietet anspruchsvolle Missionen und führt die Geschichte sinnvoll weiter. Als eigenständiger Einstieg eignet sich das Add-on dagegen weniger, da es auf den Mechaniken und der Handlung des Hauptspiels aufbaut.`,
