        folder: "riddle_of_master_lu",
        scanBy: "Magisthan",
        page: "riddle_of_master_lu.html",
        featured: false,
        title: "Ripley's Believe It or Not!: The Riddle of Master Lu",
        system: "PC",
        year: 1995,        
        publisher: "U.S. Gold",
        developer: "Sanctuary Woods Multimedia",
        genre: ["Adventure", "Point-and-Click", "Mystery"],
        description: "The Riddle of Master Lu ist ein aufwendig inszeniertes Point-and-Click-Adventure, das den Abenteurer Robert Ripley 1936 auf die Suche nach einem geheimnisvollen chinesischen Artefakt schickt.",
        history: `The Riddle of Master Lu spielt im Jahr 1936 und stellt den realen Abenteurer, Weltreisenden und Kuriositätensammler Robert Ripley in den Mittelpunkt einer fiktiven Geschichte. Nach einem Zwischenfall in Ägypten entdeckt Ripley, dass unbekannte Männer offenbar nach Informationen über den geheimnisvollen Master Lu suchen. Die Spur führt zu einem sagenumwobenen Smaragdsiegel aus dem Grab des ersten chinesischen Kaisers, dem enorme Macht zugeschrieben wird. Gemeinsam mit seiner Begleiterin Mei Chen reist Ripley durch verschiedene Teile der Welt und versucht, das Geheimnis zu lösen, bevor das Artefakt in die falschen Hände gerät. Spielerisch handelt es sich um ein klassisches Point-and-Click-Adventure mit Dialogen, Inventarrätseln und zahlreichen exotischen Schauplätzen. Gefilmte Schauspieler, vorgerenderte Hintergründe und aufwendige Zwischensequenzen sollten dem Abenteuer eine besonders filmische Atmosphäre verleihen.`,
        review: `The Riddle of Master Lu gehört zu den Adventures der 1990er-Jahre, die heute erstaunlicherweise etwas unter dem Radar fliegen. Dabei muss sich das Spiel vor vielen bekannteren Genrevertretern keineswegs verstecken. Die Geschichte besitzt genau die richtige Mischung aus Indiana-Jones-Abenteuer, historischen Geheimnissen und einer gehörigen Portion Pulp. Besonders gelungen sind die detaillierten Schauplätze und die abwechslungsreichen Reisen rund um die Welt. Auch die Rätsel funktionieren größtenteils nach klassischer Adventure-Logik und bleiben erfreulich eng mit der Handlung verbunden. Die damals moderne Kombination aus gerenderten Hintergründen und gefilmten Schauspielern wirkt heute natürlich unverkennbar nach Mitte der 1990er, besitzt dadurch aber auch ihren ganz eigenen Charme. Wer klassische Adventures mag und bereits die großen LucasArts- und Sierra-Titel kennt, findet hier einen ausgesprochen interessanten Geheimtipp.`,
        trivia: [
                  "Robert Ripley war keine erfundene Spielfigur, sondern ein realer amerikanischer Cartoonist, Weltreisender und Sammler, auf dessen Arbeiten das bis heute bekannte Ripley's Believe It or Not! zurückgeht.",
                  "Das Spiel wurde von Lee Sheldon und François Robillard entworfen; Sheldon schrieb außerdem die Geschichte und führte gemeinsam mit Art Director Michael Gibson bei den Videosequenzen Regie.",
                  "The Riddle of Master Lu verwendet gefilmte Schauspieler vor vorgerenderten Hintergründen und verbindet damit klassisches Point-and-Click-Gameplay mit der Mitte der 1990er-Jahre populären Multimedia- und FMV-Technik."
        ],
        worthPlaying: `The Riddle of Master Lu lohnt sich heute besonders für Fans klassischer Point-and-Click-Adventures. Die Kombination aus exotischen Schauplätzen, historischen Geheimnissen, klassischen Inventarrätseln und einer angenehm pulpigen Abenteuergeschichte funktioniert noch immer hervorragend. Gerade weil der Titel heute deutlich weniger bekannt ist als die großen Adventures von LucasArts oder Sierra, lässt sich hier noch ein echtes Kleinod der Adventure-Ära entdecken.`,
