        id: 48,
        folder: "bundesliga_manager_97",
        scanBy: "Magisthan",
        page: "bundesliga_manager_97.html",
        featured: false,
        title: "Bundesliga Manager 97",
        system: "PC",
        year: 1996,        
        publisher: "Software 2000",
        developer: "Software 2000",
        genre: ["Fußballmanager", "Wirtschaftssimulation", "Sport"],
        description: "Bundesliga Manager 97 ist eine umfangreiche Fußball-Managementsimulation, in der du einen Verein sportlich und wirtschaftlich führst und erstmals in der Serie auch 3D-Spielszenen verfolgen kannst.",
        history: `Bundesliga Manager 97 erschien Ende 1996 für den PC und war der vierte große Teil der erfolgreichen Bundesliga-Manager-Reihe von Software 2000. Wie schon in den Vorgängern übernimmt der Spieler die komplette Leitung eines Fußballvereins und kümmert sich um Aufstellung, Transfers, Training, Finanzen, Stadion und zahlreiche weitere wirtschaftliche Entscheidungen. Neu waren unter anderem aufwendigere Hi-Color-Grafiken und dreidimensionale Spielszenen, mit denen Software 2000 die Serie technisch modernisieren wollte. Hinter dem Spiel standen erneut Werner Krahe und Jens Onnen, die bereits die früheren Bundesliga-Manager-Titel maßgeblich geprägt hatten. Die Veröffentlichung verlief allerdings problematisch: Die ursprüngliche Verkaufsversion enthielt zahlreiche Fehler und hinterließ bei vielen Spielern einen unfertigen Eindruck. Software 2000 veröffentlichte anschließend mehrere Patches; spätere Versionen waren deutlich stabiler. International erschien das Spiel unter anderem als Total Football Management.`,
        review: `Bundesliga Manager 97 ist ein interessantes Beispiel dafür, wie eine eigentlich etablierte Serie an zu viel Ehrgeiz und zu wenig Feinschliff stolpern kann. Inhaltlich steckt enorm viel im Spiel: Transfers, Training, Taktik, Stadionausbau und Vereinsfinanzen bieten genug Beschäftigung für viele virtuelle Saisons. Auch die neuen 3D-Spielszenen waren 1996 ein nachvollziehbarer Versuch, die Reihe technisch auf die nächste Stufe zu heben. Das eigentliche Problem war der Zustand der ursprünglichen Veröffentlichung. Zahlreiche Bugs überschatteten viele der guten Ideen und sorgten dafür, dass der Nachfolger von Bundesliga Manager Hattrick bei Fans deutlich schlechter ankam als erhofft. In einer später gepatchten Version bleibt trotzdem eine komplexe und durchaus unterhaltsame Fußball-Wirtschaftssimulation, die vor allem für Serienfans interessant ist.`,
        trivia: [
                  "Bundesliga Manager 97 erschien international unter dem Namen „Total Football Management“; in Frankreich wurde eine spätere Variante als „Guy Roux Manager 98“ veröffentlicht.",
                  "Die Erstauflage wurde wegen zahlreicher Programmfehler berüchtigt. Laut Berichten wurde versehentlich ein falscher, unfertiger Master zur Produktion geschickt und anschließend über mehrere Monate mit Patches nachgebessert.",
                  "Werner Krahe und Jens Onnen arbeiteten seit den Anfängen der Reihe gemeinsam an den Bundesliga-Manager-Spielen; Bundesliga Manager 97 war ihr letzter Teil der Serie, bevor beide Software 2000 verließen."
        ],
        worthPlaying: `Bundesliga Manager 97 lohnt sich heute vor allem für Freunde klassischer deutscher Fußballmanager und als wichtiger Teil der Geschichte von Software 2000. In einer gepatchten Fassung bietet das Spiel eine umfangreiche Mischung aus Sport- und Wirtschaftssimulation mit vielen Stellschrauben. Gleichzeitig ist es ein interessantes Zeitdokument dafür, wie stark ein technisch problematischer Verkaufsstart den Ruf einer etablierten Spielereihe beschädigen kann.`,
