        developer: "Westwood Studios",
        genre: ["Echtzeitstrategie", "Science-Fiction", "Strategie"],
        description: "Command & Conquer: Tiberian Sun ist ein düsteres Echtzeitstrategiespiel, in dem GDI und Nod in einer vom Tiberium gezeichneten Zukunft erneut um die Vorherrschaft kämpfen.",
        history: `Command & Conquer: Tiberian Sun erschien 1999 als direkter Nachfolger des ersten Command & Conquer und verlegt den Konflikt zwischen der Global Defense Initiative und der Bruderschaft von Nod in eine deutlich düsterere Zukunft. Die Erde ist inzwischen massiv vom Tiberium verändert worden, ganze Regionen sind ökologisch zerstört und neue Lebensformen sowie Mutationen breiten sich aus. Gleichzeitig kehrt Kane zurück und führt Nod in einen weiteren Krieg gegen die GDI. Spielerisch bleibt Tiberian Sun dem klassischen Westwood-Prinzip treu: Basen errichten, Tiberium sammeln, Einheiten produzieren und den Gegner militärisch ausschalten. Die neue Engine ermöglichte unter anderem Höhenunterschiede, zerstörbare Brücken, deformierbares Gelände sowie Einheiten, die schweben oder sich unterirdisch bewegen können. Die englische Originalfassung enthält die unzensierten menschlichen Soldaten und Filmsequenzen, die in der deutschen Version teilweise verändert oder entschärft wurden.`,
        review: `Tiberian Sun lebt von seiner Atmosphäre. Während frühere Command-&-Conquer-Spiele noch deutlich näher an klassischer Militärtechnik lagen, wirkt hier fast alles fremder, futuristischer und bedrohlicher. Die zerstörte Welt, das wuchernde Tiberium und die markanten Einheiten geben dem Spiel eine Identität, die innerhalb der Reihe bis heute heraussticht. Spielerisch funktioniert die bekannte Mischung aus Basisbau, Ressourcenmanagement und schnellen Angriffen weiterhin hervorragend, auch wenn Wegfindung und KI gelegentlich ihre ganz eigenen Vorstellungen davon entwickeln, wie eine Einheit ihr Ziel erreichen sollte. Die englische Version wirkt zudem etwas stimmiger als die deutsche Fassung, weil Soldaten, Sprachaufnahmen und Filmsequenzen unverändert erhalten geblieben sind. Tiberian Sun ist technisch nicht perfekt, atmosphärisch aber einer der stärksten Teile der Serie.`,
        trivia: [
                  "Die Entwicklung von Tiberian Sun begann bereits 1995 und zog sich über mehrere Jahre hin. Zahlreiche ursprünglich geplante Funktionen wurden vor Veröffentlichung gestrichen.",
                  "Die englische Originalfassung enthält menschliche Soldaten und ungekürzte Filmsequenzen, während die deutsche Version mehrere Inhalte veränderte und Soldaten weitgehend als Cyborgs darstellte.",
                  "In den Filmsequenzen treten bekannte Schauspieler auf, darunter Michael Biehn als Michael McNeil und James Earl Jones als General James Solomon."
        ],
        worthPlaying: `Command & Conquer: Tiberian Sun lohnt sich heute besonders wegen seiner unverwechselbaren Science-Fiction-Atmosphäre. Die englische Originalfassung bietet dabei die unveränderte Präsentation mit Originalstimmen und unzensierten Inhalten. Wer klassischen Basisbau, große Armeen und die typische Westwood-Mischung aus Strategie und aufwendig inszenierten Filmsequenzen mag, bekommt hier einen der charakteristischsten Teile der gesamten Command-&-Conquer-Reihe.`,
