        id: 54,
        folder: "cosmic_relief",
        scanBy: "Magisthan",
        page: "cosmic_relief.html",
        featured: false,
        title: "Cosmic Relief: Prof. Renegade to the Rescue",
        system: "C64",
        year: 1988,        
        publisher: "Datasoft, Inc.",
        developer: "Teque Software Development Ltd.",
        genre: ["Action-Adventure", "Puzzle", "Plattform"],
        description: "Cosmic Relief ist ein skurriles Action-Adventure mit Puzzle- und Plattformelementen, in dem du Professor Renegade finden und eine drohende Asteroidenkatastrophe verhindern musst.",
        history: `Cosmic Relief: Prof. Renegade to the Rescue erschien Ende der 1980er Jahre für mehrere Heimcomputer und wurde von Teque Software Development entwickelt. Die C64-Version kam 1988 auf den Markt und wurde in den USA von Datasoft veröffentlicht. Ausgangspunkt der Handlung ist die Vorhersage von Professor K.K. Renegade, dass ein gewaltiger Asteroid auf die Erde zurast. Der Professor selbst ist allerdings verschwunden und wurde zuletzt in einer abgelegenen Region des Himalaya gesehen. Der Spieler wählt einen von fünf Abenteurern aus verschiedenen Ländern und macht sich auf die Suche nach ihm. Spielerisch kombiniert Cosmic Relief Erkundung, Plattform-Elemente und Rätsel. Zahlreiche ungewöhnliche Gegenstände wie Sporen, ein Staubsauger oder ein Einrad müssen gefunden und an der richtigen Stelle eingesetzt werden. Zusätzlich läuft im Hintergrund ein Zeitlimit, denn dem Spieler bleiben nur 30 Tage, um den Professor zu finden und eine Vorrichtung gegen den Asteroiden zu bauen.`,
        review: `Cosmic Relief ist eines dieser Spiele, bei denen man schon nach wenigen Minuten merkt, dass hier niemand versucht hat, besonders normal zu sein. Das ist durchaus positiv gemeint. Statt klassischer Science-Fiction bekommt man eine schräge Mischung aus Abenteuer, Plattformspiel und Gegenstandsrätseln, bei der ein Staubsauger oder ein Einrad plötzlich genauso wichtig sein können wie gutes Timing. Die C64-Version besitzt eine eigenwillige, aber sympathische Atmosphäre und lebt vor allem von ihren ungewöhnlichen Ideen. Nicht immer ist sofort klar, welcher Gegenstand wofür gedacht ist, und manche grafische Darstellung kann mehr Verwirrung als Hilfe erzeugen. Trotzdem bleibt Cosmic Relief interessant, weil es nicht wie das hundertste Standard-Plattformspiel seiner Zeit wirkt. Wer gerne experimentiert und auch einmal an etwas seltsamen Rätseln hängen bleibt, findet hier einen charmanten Außenseiter.`,
        trivia: [
                  "Cosmic Relief ist in Europa auch unter dem Titel „Terramex“ erschienen.",
                  "Die C64-Version wurde von Peter Harrap und Shaun Hollingworth programmiert; die Musik stammt von Ben Daglish.",
                  "Für die europäischen Veröffentlichungen wird Steinar Lund ausdrücklich als Cover-Künstler genannt."
        ],
        worthPlaying: `Cosmic Relief lohnt sich heute vor allem für Spieler, die ungewöhnliche C64-Titel mögen. Die Mischung aus Action, Erkundung und teils absurden Gegenstandsrätseln hebt das Spiel deutlich von vielen zeitgenössischen Plattformspielen ab. Gerade die skurrile Atmosphäre und das ungewöhnliche Szenario machen den Titel trotz einiger sperriger Stellen auch heute noch interessant.`,
