        genre: ["Action-Rollenspiel", "Action-Adventure", "Fantasy"],
        description: "Crusaders of Might and Magic ist ein Third-Person-Action-Rollenspiel, in dem der Krieger Drake mit Schwert, Magie und zunehmend besserer Ausrüstung gegen die untote Legion of the Fallen antritt.",
        history: `Crusaders of Might and Magic erschien 1999 für Windows und versuchte, die bekannte Might-and-Magic-Marke in Richtung eines actionorientierten Third-Person-Abenteuers zu erweitern. Der Spieler übernimmt die Rolle von Drake, dessen Familie von der Legion of the Fallen ausgelöscht wurde. Jahre später gerät er erneut in den Konflikt und schließt sich dem Kampf gegen die untote Armee und ihren Anführer Necros an. Statt einer klassischen Gruppen-Rollenspielstruktur steuert der Spieler Drake direkt durch dreidimensionale Umgebungen. Gekämpft wird mit Schwertern, Äxten, Streitkolben und Magie, während neue Ausrüstung und Erfahrungspunkte den Helden stärker machen. Die PC- und PlayStation-Versionen entstanden getrennt voneinander und unterscheiden sich deshalb deutlich in Aufbau und Technik.`,
        review: `Crusaders of Might and Magic ist ein gutes Beispiel dafür, dass ein bekannter Name allein noch kein gutes Rollenspiel macht. Die Idee, Might and Magic als direkt gesteuertes Action-Rollenspiel umzusetzen, klingt zunächst durchaus reizvoll. Tatsächlich funktionieren Kämpfe, Ausrüstung und Magie grundsätzlich ordentlich, und einige Bereiche besitzen eine durchaus passende Fantasy-Atmosphäre. Das Problem ist eher, dass viele dieser Elemente nicht besonders tief ausgearbeitet wurden. Die Umgebungen wirken häufig leer, Gegner wiederholen sich und die Rollenspielmechanik bleibt deutlich oberflächlicher als bei den klassischen Might-and-Magic-Spielen. Dadurch entsteht ein Spiel, das selten wirklich schlecht, aber ebenso selten besonders spannend ist. Wer mit der Erwartung eines großen Might-and-Magic-Abenteuers startet, dürfte deshalb ziemlich schnell ernüchtert sein.`,
        trivia: [
                  "Die Windows-Version wurde von Joshua M. Cloud inszeniert, während Michael Wallin als Lead Artist und Robert King als Komponist beteiligt waren.",
                  "Die PC- und PlayStation-Versionen wurden von unterschiedlichen Teams entwickelt und unterscheiden sich deshalb deutlich in Levelaufbau, Technik und Spielmechanik.",
                  "Die Zwischensequenzen der Windows-Version wurden von Hypnotix produziert, einem Studio, das später unter anderem für Outlaw Golf bekannt wurde."
        ],
        worthPlaying: `Crusaders of Might and Magic lohnt sich heute vor allem für Fans der Might-and-Magic-Reihe, die auch deren ungewöhnlichere Ausflüge kennenlernen möchten. Das Spiel besitzt einige charmante Fantasy-Ideen und bietet unkomplizierte Action, erreicht aber weder die Tiefe der klassischen Rollenspiele noch die Qualität der stärksten Action-Adventures seiner Zeit. Als Kuriosität innerhalb der Seriengeschichte ist es dennoch interessant.`,
