        id: 57,
        folder: "das_amt",
        scanBy: "Magisthan",
        page: "das_amt.html",
        featured: false,
        title: "Das Amt",
        system: "PC",
        year: 1995,        
        publisher: "Greenwood Entertainment Software GmbH",
        developer: "Greenwood Entertainment Software GmbH",
        genre: ["Wirtschaftssimulation", "Politiksimulation", "Management"],
        description: "Das Amt ist eine humorvolle politische Wirtschaftssimulation, in der du als frisch gewählter Bürgermeister einer bayerischen Gemeinde zwischen Haushalt, Gemeinderat, Lobbygruppen und ganz persönlichen Interessen jonglierst.",
        history: `Das Amt erschien 1995 für MS-DOS und wurde von Greenwood Entertainment entwickelt und veröffentlicht. Das Spiel versetzt den Spieler in die Rolle des Bürgermeisters der fiktiven bayerischen Gemeinde Tupfingen. Zu Beginn werden politische Ziele und eine eigene Partei festgelegt, anschließend beginnt der ganz normale kommunalpolitische Wahnsinn. Bauvorhaben müssen genehmigt, Straßen geplant, Betriebe unterstützt und die verschiedenen Interessengruppen der Gemeinde bei Laune gehalten werden. Eine Spielrunde entspricht einer Woche und muss innerhalb eines begrenzten Zeitfensters abgearbeitet werden. Besonderen Reiz erhält das Spiel durch seinen satirischen Ton: Korruption, persönliche Bereicherung und politische Gefälligkeiten gehören ebenso zum Spielprinzip wie seriöse Verwaltungsarbeit. Zusätzlich besitzt der Bürgermeister einen eigenen Betrieb, dessen Gewinne für mehr oder weniger diskrete politische Zwecke genutzt werden können.`,
        review: `Das Amt gehört zu jener Sorte deutscher Wirtschaftssimulationen, bei denen schon die Themenwahl dafür sorgt, dass man zweimal hinsieht. Statt Eisenbahn, Fußballverein oder Transportunternehmen wartet hier der Arbeitsplatz, von dem viele Menschen normalerweise nur dann etwas hören möchten, wenn möglichst wenig Papier ausgefüllt werden muss. Gerade das macht den Reiz aus. Greenwood nimmt Kommunalpolitik nicht übermäßig ernst und verwandelt den Alltag eines Bürgermeisters in eine Mischung aus Wirtschaftssimulation, Satire und politischem Überlebenskampf. Hinter der humorvollen Oberfläche steckt dennoch ein überraschend komplexes Geflecht aus Interessen, Betrieben, Gemeinderäten und Finanzen. Die Bedienung wirkt heute natürlich deutlich altmodischer, und manche Abläufe sind sperriger als nötig. Wer jedoch deutsche Aufbauspiele und Wirtschaftssimulationen der 1990er mag, bekommt hier einen ungewöhnlichen und erstaunlich eigenständigen Vertreter.`,
        trivia: [
                  "Die Idee und Programmierung stammen von Holger Dickmann, der später unter dem Namen Holger Beisheim bekannt wurde und Greenwood Entertainment mitgründete.",
                  "Ogan Kandemiroglu und Celal Kandemiroglu werden in den Credits ausdrücklich für das Artwork genannt.",
                  "Das Spiel verwendet reale ZDF-Sequenzen und Logos; in den Credits wird außerdem der Bund der Steuerzahler als Quelle für Hintergrundmaterial aufgeführt."
        ],
        worthPlaying: `Das Amt ist heute vor allem deshalb interessant, weil kaum ein anderes Spiel der 1990er Jahre deutsche Kommunalpolitik auf diese Weise mit Wirtschaftssimulation und Satire verbindet. Wer Titel wie Der Planer, Vermeer oder andere deutschsprachige Managementspiele dieser Zeit mag, findet hier ein ungewöhnliches Stück deutscher Computerspielgeschichte. Die Mischung aus seriöser Verwaltung, politischem Taktieren und ziemlich unverhohlener Bestechung besitzt auch heute noch einen ganz eigenen Charme.`,
