        id: 58,
        folder: "der_korsar",
        scanBy: "Magisthan",
        page: "der_korsar.html",
        featured: false,
        title: "Der Korsar",
        system: "PC",
        year: 1999,        
        publisher: "Microïds",
        developer: "Microïds",
        genre: ["Strategie", "Wirtschaftssimulation", "Echtzeitstrategie"],
        description: "Der Korsar ist eine Mischung aus Piratenabenteuer, Handel und Echtzeitstrategie, in der du im 17. Jahrhundert als Freibeuter durch die Karibik segelst, Handel treibst, Schiffe enterst und feindliche Stützpunkte angreifst.",
        history: `Der Korsar erschien 1999 für Windows und wurde vom französischen Studio Microïds entwickelt. International ist das Spiel als Corsairs beziehungsweise Corsairs: Conquest at Sea bekannt. Inhaltlich erinnert das Konzept unübersehbar an Sid Meier's Pirates!: Als Freibeuter segelt der Spieler durch die Karibik des 17. Jahrhunderts, besucht Häfen, handelt mit Waren und versucht gleichzeitig, den Einfluss der eigenen Nation auszubauen. Dabei bleibt es jedoch nicht beim friedlichen Warentransport. Feindliche Schiffe können mit Kanonen bekämpft und anschließend geentert werden. Bei Enterkämpfen wechselt das Spiel in eine isometrische Echtzeitstrategieansicht, in der Matrosen und Offiziere direkt kontrolliert werden. Auch feindliche Handelsposten und Piratenstützpunkte können angegriffen werden. Die Kombination aus Handel, Seefahrt und taktischen Gefechten sollte das klassische Piratenspielprinzip in eine modernere Echtzeitstrategieform übertragen.`,
        review: `Der Korsar ist eines dieser Spiele, bei denen man ziemlich schnell erkennt, welches große Vorbild auf dem Schreibtisch der Entwickler gelegen haben dürfte. Sid Meier's Pirates! lässt freundlich grüßen, trotzdem versucht Microïds genug eigene Ideen einzubauen. Besonders die Kombination aus Handel, Flottenmanagement, Segelgefechten und isometrischen Enterkämpfen besitzt ihren Reiz. Gerade auf See entwickelt das Spiel eine angenehm ruhige Piratenatmosphäre, bei der man schnell noch einen Hafen besuchen möchte und plötzlich feststellt, dass der Abend verschwunden ist. Ganz rund ist das Abenteuer allerdings nicht. Bedienung und Wegfindung können störrisch sein, die Kämpfe wiederholen sich und manche Spielmechanik bleibt weniger ausgearbeitet, als das ambitionierte Konzept vermuten lässt. Trotzdem besitzt Der Korsar einen eigenständigen Charme und ist gerade für Freunde klassischer Piratenspiele ein interessanter Geheimtipp.`,
        trivia: [
                  "Der Korsar erschien international unter den Titeln Corsairs und Corsairs: Conquest at Sea; die deutsche Veröffentlichung trägt dagegen schlicht den Titel Der Korsar.",
                  "Die zeitgenössischen deutschen Wertungen gingen deutlich auseinander: PC Action vergab 76 Prozent, während GameStar nur 52 Prozent Spielspaß errechnete.",
                  "Fabien Laouer wird in den offiziellen Credits ausdrücklich als Cover Artist genannt; außerdem war er zusammen mit Donald Simpson, Mr. Wang und Eric Royou am Package Design beteiligt."
        ],
        worthPlaying: `Der Korsar lohnt sich heute besonders für Spieler, die Sid Meier's Pirates! mögen und eine etwas stärker auf Echtzeitstrategie ausgerichtete Variante des Piratenthemas ausprobieren möchten. Handel, Segeln, Kanonengefechte und Enterkämpfe ergeben trotz einiger technischer und spielerischer Ecken eine ungewöhnliche Mischung. Gerade die entschleunigte Karibikatmosphäre sorgt dafür, dass das Spiel auch heute noch einen gewissen Reiz besitzt.`,
