        id: 59,
        folder: "die_schicksalsklinge_cdrom",
        scanBy: "Magisthan",
        page: "die_schicksalsklinge_cdrom.html",
        featured: false,
        title: "Das Schwarze Auge: Die Schicksalsklinge",
        system: "PC",
        year: 1994,        
        publisher: "Fantasy Productions",
        developer: "Attic Entertainment Software",
        genre: ["Rollenspiel", "Fantasy", "Dungeon Crawler"],
        description: "Die Schicksalsklinge ist der Auftakt der Nordlandtrilogie und setzt das Regelwerk von Das Schwarze Auge ungewöhnlich detailliert als umfangreiches Computer-Rollenspiel um.",
        history: `Das Schwarze Auge: Die Schicksalsklinge erschien ursprünglich 1992 für DOS und bildete den Auftakt der später als Nordlandtrilogie bekannten Rollenspielserie von Attic Entertainment. Die hier erfasste CD-ROM-Version folgte später und erweiterte die ursprüngliche Ausgabe unter anderem um Sprachausgabe. Schauplatz ist Aventurien, die Fantasywelt des deutschen Pen-&-Paper-Rollenspiels Das Schwarze Auge. Im Norden des Kontinents droht eine gewaltige Orkarmee die menschlichen Siedlungen zu überrennen. Eine Gruppe von sechs Helden erhält den Auftrag, die legendäre Schicksalsklinge Grimring zu finden, mit deren Hilfe der Orkhäuptling besiegt werden kann. Statt einer streng linearen Handlung bietet das Spiel eine frei erkundbare Welt mit zahlreichen Städten, Dörfern, Dungeons und Nebenaufgaben. Reisen müssen geplant, Vorräte eingekauft und Krankheiten sowie Verletzungen behandelt werden. Kämpfe laufen rundenbasiert auf taktischen Feldern ab. Besonders bemerkenswert ist die detaillierte Umsetzung des DSA-Regelwerks mit zahlreichen Charakterwerten, Talenten, Zaubern und Ausrüstungsgegenständen.`,
        review: `Die Schicksalsklinge ist ein Rollenspiel aus einer Zeit, in der ein Abenteuer noch der Meinung war, dass der Spieler ruhig selbst herausfinden darf, warum seine Heldengruppe gerade halb verhungert und mit drei Krankheiten durch den verschneiten Norden Aventuriens taumelt. Komfort wird hier eher als optionales Talent behandelt. Genau darin liegt aber ein großer Teil des Reizes. Attic hat das Regelwerk von Das Schwarze Auge erstaunlich konsequent in ein Computerspiel übertragen. Reisen, Krankheiten, Nahrung, Talente und Charakterwerte sind nicht bloß Dekoration, sondern beeinflussen das Abenteuer tatsächlich. Das macht den Einstieg sperrig und verlangt Geduld, erzeugt aber eine Rollenspieltiefe, die selbst viele wesentlich modernere Titel nicht erreichen. Die CD-ROM-Version macht das Abenteuer durch ihre zusätzlichen Audioelemente etwas zugänglicher. Wer bereit ist, sich auf die komplexen Systeme einzulassen, bekommt einen der bedeutendsten deutschen Computer-Rollenspielklassiker.`,
        trivia: [
                  "Die Schicksalsklinge ist der erste Teil der sogenannten Nordlandtrilogie. Es folgten Sternenschweif und Schatten über Riva.",
                  "Die CD-ROM-Ausgabe erweitert die ursprüngliche Diskettenversion unter anderem um Sprachausgabe und zusätzliche audiovisuelle Elemente.",
                  "Spielstände beziehungsweise Heldengruppen können in den Nachfolger Sternenschweif übernommen und später bis in Schatten über Riva weitergeführt werden."
        ],
        worthPlaying: `Die Schicksalsklinge lohnt sich heute vor allem wegen ihrer außergewöhnlichen Rollenspieltiefe und der konsequenten Umsetzung des DSA-Regelwerks. Wer moderne Komfortfunktionen erwartet, wird zunächst einige Kulturschocks erleben. Wer dagegen Freude an Charakterentwicklung, Erkundung, Reiseplanung und einer glaubwürdigen Fantasywelt hat, entdeckt einen Meilenstein deutscher Rollenspielgeschichte. Die Möglichkeit, dieselbe Heldengruppe durch die komplette Nordlandtrilogie zu führen, verstärkt diesen Reiz zusätzlich.`,
