        id: 74,
        folder: "ghostbusters_2",
        scanBy: "Magisthan",
        page: "ghostbusters_2.html",
        featured: false,
        title: "Ghostbusters II",
        system: "C64",
        year: 1989,        
        publisher: "Activision, Inc.",
        developer: "Foursfield",
        genre: ["Action", "Arcade", "Filmumsetzung"],
        description: "Ghostbusters II ist die C64-Umsetzung des gleichnamigen Kinofilms und verarbeitet drei zentrale Filmszenen als unterschiedliche Action- und Geschicklichkeitsabschnitte.",
        history: `Ghostbusters II erschien 1989 passend zum zweiten Kinofilm und wurde für den Commodore 64 von Foursfield entwickelt und von Activision veröffentlicht. Anders als die separate DOS-Version von Dynamix orientiert sich diese Fassung an drei ausgewählten Szenen des Films. Zunächst wird Ray Stantz in den Untergrund von New York hinabgelassen, um eine Probe aus dem Fluss aus rosa Schleim zu entnehmen. Dabei muss er Hindernissen und Geistern ausweichen und die benötigte Ausrüstung einsammeln. Im zweiten Abschnitt steuert der Spieler die Freiheitsstatue durch New York und verteidigt sie gegen angreifende Geister, während der Vorrat an positivem Schleim ständig abnimmt. Das Finale spielt schließlich im Museum, wo die Ghostbusters zunächst an Seilen in das Gebäude hinabgelassen werden und anschließend gegen Janosz und Vigo antreten. Die C64-Version wurde von Paul Baker programmiert, Steven Green war für die Grafik verantwortlich und David Whittaker kümmerte sich um Musik und Sound.`,
        review: `Ghostbusters II hat eigentlich alles, was ein gutes Lizenzspiel braucht: eine populäre Filmvorlage, Geister, Protonenstrahler, die Freiheitsstatue und einen Fluss voller rosa Schleim. Das Problem ist nur, dass daraus auf dem C64 kein besonders gutes Spiel geworden ist. Die Idee, drei bekannte Filmszenen als unterschiedliche Spielabschnitte umzusetzen, klingt zunächst abwechslungsreich. Vor allem der Abstieg in den Schleimkanal besitzt sogar eine gewisse Atmosphäre. Danach wird es allerdings deutlich dünner. Die Abschnitte sind kurz, die Steuerung teilweise störrisch und einige Spielmechaniken erschließen sich eher durch Versuch und Irrtum als durch gutes Design. David Whittakers Musik und die erkennbare Nähe zum Film retten einiges von der Präsentation, aber spielerisch bleibt Ghostbusters II deutlich hinter dem ersten Ghostbusters zurück. Für Fans der Filme ist es ein interessantes Stück Lizenzspielgeschichte, für alle anderen eher ein Fall für die Geisterfalle.`,
        trivia: [
                  "Die C64-Version wurde von Foursfield entwickelt und unterscheidet sich deutlich von der ebenfalls 1989 veröffentlichten DOS-Version von Dynamix.",
                  "Paul Baker programmierte die C64-Fassung, Steven Green war für die Grafik verantwortlich und David Whittaker übernahm Musik und Sound.",
                  "Das Spiel besteht lediglich aus drei großen Abschnitten, die den Schleimfluss unter New York, die Fahrt der Freiheitsstatue und den abschließenden Kampf gegen Vigo im Museum aufgreifen."
        ],
        worthPlaying: `Ghostbusters II lohnt sich heute vor allem für Fans der Filme und Sammler klassischer C64-Lizenzspiele. Die drei unterschiedlichen Spielabschnitte greifen einige der bekanntesten Szenen des zweiten Films auf und David Whittakers Soundtrack sorgt für zusätzlichen C64-Charme. Spielerisch ist die Umsetzung allerdings ziemlich durchwachsen und deutlich weniger gelungen als ihr berühmter Vorgänger.`,
        letsPlay: "",
