        id: 76,
        folder: "all_new_world_of_lemmings",
        scanBy: "MK2k - https://bigbox3d.net",
        page: "all_new_world_of_lemmings.html",
        featured: false,
        title: "All New World of Lemmings",
        system: "PC",
        year: 1994,        
        publisher: "Psygnosis Limited",
        developer: "DMA Design Limited",
        genre: ["Puzzle", "Strategie", "Geschicklichkeit"],
        description: "All New World of Lemmings ist der dritte große Teil der klassischen Lemmings-Reihe und schickt drei verbliebene Stämme durch insgesamt 90 neue Puzzle-Level.",
        history: `All New World of Lemmings erschien 1994 für DOS und wurde von DMA Design entwickelt sowie von Psygnosis veröffentlicht. In Nordamerika erschien das Spiel unter dem Titel The Lemmings Chronicles. Inhaltlich knüpft es an Lemmings 2: The Tribes an, reduziert die zuvor zwölf Stämme jedoch auf drei: Classic, Egyptian und Shadow. Jeder Stamm besitzt ein eigenes grafisches Thema und insgesamt 30 Level, wodurch das Spiel auf 90 Abschnitte kommt. Das Grundprinzip bleibt vertraut: Eine Gruppe von Lemmingen muss sicher vom Eingang zum Ausgang geführt werden. Gleichzeitig wurde das Fertigkeitssystem deutlich verändert. Fähigkeiten werden nun teilweise als Gegenstände direkt im Level aufgenommen und können von einzelnen Lemmingen getragen beziehungsweise wieder abgelegt werden. Zusätzlich besitzen alle Lemminge grundlegende Aktionen wie Springen, Umkehren oder Blockieren. Neu ist außerdem eine Wiederholungsfunktion, mit der bereits ausgeführte Aktionen automatisch erneut abgespielt und an einem gewünschten Punkt verändert werden können. Produziert wurde das Spiel von David Jones, die DOS-Programmierung übernahmen Russel Elliot, Robert Parsons, Keith R. Hamilton und Steven Reid.`,
        review: `All New World of Lemmings versucht etwas, das bei einer so etablierten Serie immer riskant ist: Es verändert die Regeln, ohne das eigentliche Spielprinzip komplett über Bord zu werfen. Das neue Fertigkeitssystem sorgt dafür, dass man stärker mit einzelnen Lemmingen arbeiten muss und weniger einfach nur Befehle aus einer Leiste verteilt. Das macht viele Level interessanter, kann aber auch dazu führen, dass man sich etwas mehr mit der Bedienung beschäftigt als einem lieb ist. Die drei Stämme sind optisch schön voneinander getrennt und die 90 Level bieten reichlich Stoff für Freunde gepflegter Lemming-Rettungsaktionen. Gleichzeitig fehlt ein wenig die unmittelbare Klarheit des Originals. Wer aber nach Lemmings 2 noch nicht genug von kleinen grünen Haaren und kollektivem Abgrundverhalten hatte, bekommt hier einen cleveren und durchaus eigenständigen dritten Teil.`,
        trivia: [
                  "In Nordamerika erschien All New World of Lemmings unter dem Titel The Lemmings Chronicles.",
                  "Das Spiel enthält insgesamt 90 Level, verteilt auf die drei Stämme Classic, Egyptian und Shadow mit jeweils 30 Abschnitten.",
                  "Die Cover-Illustration stammt von Dave Pether; David Osborne war als Art Director für das Projekt verantwortlich."
        ],
        worthPlaying: `All New World of Lemmings lohnt sich heute vor allem für Spieler, die die klassische Reihe bereits kennen und eine etwas andere Variante des bekannten Spielprinzips suchen. Das überarbeitete Fertigkeitssystem und die drei klar unterschiedlichen Themenwelten sorgen für genügend Eigenständigkeit, während das Grundgefühl von Lemmings erhalten bleibt. Gerade als Abschluss der klassischen DMA-Design-Ära ist der Titel außerdem historisch besonders interessant.`,
        letsPlay: "",
